{"content":"import { ref, type Ref } from "vue";

/**
 * Split the total typed character count into launcher and suffix portions,
 * accounting for whether an icon takes up a virtual character slot.
 */
export function computeTypedSlices(
  launcher: string,
  suffix: string,
  charCount: number,
  iconOffset: number,
) {
  const typedLauncher = launcher.slice(
    0,
    Math.min(Math.max(0, charCount - iconOffset), launcher.length),
  );
  const typedSuffix = suffix.slice(
    0,
    Math.max(0, charCount - iconOffset - launcher.length),
  );
  return {
    typedLauncher,
    typedSuffix,
    visibleText: `${typedLauncher}${typedSuffix}`,
  };
}

/**
 * Creates a cursor blinking controller for typing cycle animations.
 */
export function createCursorBlink(blinkMs: number): {
  cursorBlink: Ref<boolean>;
  beatBlink: () => void;
  clearBlinkTimer: () => void;
} {
  const cursorBlink = ref(false);
  let blinkTimeoutId: ReturnType<typeof setTimeout> | undefined;

  function clearBlinkTimer() {
    clearTimeout(blinkTimeoutId);
  }

  function beatBlink() {
    cursorBlink.value = false;
    clearTimeout(blinkTimeoutId);
    requestAnimationFrame(() => {
      cursorBlink.value = true;
      blinkTimeoutId = setTimeout(() => {
        cursorBlink.value = false;
      }, blinkMs);
    });
  }

  return { cursorBlink, beatBlink, clearBlinkTimer };
}
